#!/usr/bin/env node
// Bundles the shopper-facing legal drafts (docs/legal/*.{ar,en}.md) into a typed TS module for the mobile app.
// Usage: node tooling/legal/bundle.mjs [--check]   (--check fails when the generated file is stale)
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join, dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..");
const OUT = join(root, "apps/mobile/src/features/legal/generated/legal-docs.ts");

/** Shopper-facing documents only. Seller agreement and DPA annex stay out of the shopper app. */
export const DOCS = [
  "terms-of-service", "privacy-policy", "returns-refunds-policy", "plus-subscription-terms", "store-credit-terms",
  "gift-card-terms", "rewards-referral-terms", "review-guidelines", "prohibited-items", "cookie-tracking-notice",
  "ip-takedown-procedure", "accessibility-statement",
];

export function render() {
  const entries = DOCS.map((id) => {
    const en = readFileSync(join(root, "docs/legal", `${id}.en.md`), "utf8");
    const ar = readFileSync(join(root, "docs/legal", `${id}.ar.md`), "utf8");
    return `  ${JSON.stringify(id)}: { en: ${JSON.stringify(en)}, ar: ${JSON.stringify(ar)} },`;
  });
  return `// GENERATED by tooling/legal/bundle.mjs from docs/legal/*.md. Do not edit. DRAFTS for counsel review, not in force.
export const LEGAL_DOC_IDS = ${JSON.stringify(DOCS)} as const;
export type LegalDocId = (typeof LEGAL_DOC_IDS)[number];
export const LEGAL_DOCS: Readonly<Record<LegalDocId, { readonly en: string; readonly ar: string }>> = {
${entries.join("\n")}
};
`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const next = render();
  if (process.argv.includes("--check")) {
    if (!existsSync(OUT) || readFileSync(OUT, "utf8") !== next) {
      console.error("legal bundle is stale: run node tooling/legal/bundle.mjs");
      process.exit(1);
    }
  } else {
    writeFileSync(OUT, next);
    console.log(`wrote ${OUT} (${next.length} bytes)`);
  }
}
